"""Original camera-based controller for one Panda pick-and-orient episode.
Only RGB-D images, camera calibration, task target and robot proprioception
are used. The robot kinematic chain is a nominal hardware model.
"""
import sys, json, pathlib, time
sys.path.insert(0, '/opt/tools')
import numpy as np
from scipy.spatial.transform import Rotation as Rot
from scipy.optimize import least_squares, minimize
from scipy.ndimage import binary_erosion
from PIL import Image
from rcb_client import Robot
OUT=pathlib.Path('/app/output'); RUN=pathlib.Path('/app/runs')

def rx(a): return Rot.from_rotvec([a,0,0]).as_matrix()
def rz(a): return Rot.from_rotvec([0,0,a]).as_matrix()
def tf(p=(0,0,0), R=None):
 t=np.eye(4); t[:3,3]=p
 if R is not None:t[:3,:3]=R
 return t
ORIGINS=[tf([0,0,.333]),tf(R=rx(-np.pi/2)),tf([0,-.316,0],rx(np.pi/2)),tf([.0825,0,0],rx(np.pi/2)),tf([-.0825,.384,0],rx(-np.pi/2)),tf(R=rx(np.pi/2)),tf([.088,0,0],rx(np.pi/2))]
LO=np.array([-2.8973,-1.7628,-2.8973,-3.0718,-2.8973,-.0175,-2.8973])
HI=np.array([2.8973,1.7628,2.8973,-.0698,2.8973,3.7525,2.8973])

def fk(q, site=.1034):
 T=np.eye(4)
 for o,a in zip(ORIGINS,q[:7]): T=T@o@tf(R=rz(a))
 return T@tf([0,0,.107],rz(-np.pi/4))@tf([0,0,site])

def ik(p,R,q0):
 def err(q):
  T=fk(q); return np.r_[(T[:3,3]-p)*5, Rot.from_matrix(R@T[:3,:3].T).as_rotvec(), .008*(q-q0)]
 sol=least_squares(err,np.clip(q0,LO+1e-5,HI-1e-5),bounds=(LO+1e-6,HI-1e-6),max_nfev=250,xtol=1e-11,ftol=1e-11,gtol=1e-11)
 T=fk(sol.x)
 print('IK residual',np.linalg.norm(T[:3,3]-p),np.linalg.norm(Rot.from_matrix(R@T[:3,:3].T).as_rotvec()),flush=True)
 return sol.x

def unproject(depth,cam,mask):
 v,u=np.nonzero(mask); z=depth[v,u].astype(float); K=np.array(cam['intrinsic_cv']); C=np.array(cam['cam2world_gl'])
 points=np.stack([(u+.5-K[0,2])/K[0,0]*z,-(v+.5-K[1,2])/K[1,1]*z,-z],1)
 return points@C[:3,:3].T+C[:3,3]

def project(points,cam):
 C=np.array(cam['cam2world_gl']); K=np.array(cam['intrinsic_cv']); p=(np.array(points)-C[:3,3])@np.linalg.inv(C[:3,:3]).T
 return np.stack([K[0,0]*p[:,0]/-p[:,2]+K[0,2],-K[1,1]*p[:,1]/-p[:,2]+K[1,2]],1)

def green(img):
 a=img.astype(float);return (a[:,:,1]>1.5*a[:,:,0]+15)&(a[:,:,1]>1.4*a[:,:,2]+15)&(a[:,:,1]>60)

def estimate(o,tag='vision'):
 clouds=[]
 for cam,img in o.last.items():
  mask=green(img)
  if cam in o.depth and mask.sum():
   cloud=unproject(o.depth[cam],o.meta['cameras'][cam],mask); clouds.append(cloud)
   print(cam,'green pixels',mask.sum(),'bbox',np.nanmin(cloud,0),np.nanmax(cloud,0),flush=True)
 if not clouds:return None
 pts=np.concatenate(clouds); np.save(OUT/(tag+'_points.npy'),pts)
 # Fit known cuboid using distance to its boundary, upright to begin.
 def residual(x):
  c=x[:3];R=rz(x[3]); local=(pts-c)@R
  d=np.abs(local)-np.array([.02,.02,.03]);return np.linalg.norm(np.maximum(d,0),axis=1)+np.minimum(np.max(d,axis=1),0)
 best=None
 for yaw in np.linspace(-np.pi/4,np.pi/4,9):
  x0=np.r_[np.median(pts,axis=0)[:2],.03,yaw]
  sol=least_squares(residual,x0,bounds=([.1,-.6,.02,-np.pi/2],[.9,.6,.1,np.pi/2]),loss='soft_l1',f_scale=.002,max_nfev=200)
  cost=np.mean(residual(sol.x)**2)
  if best is None or cost<best[0]:best=(cost,sol.x)
 print('BOX estimate mse, center,yaw',best,flush=True)
 return best[1]

class Controller:
 def __init__(self):
  self.r=Robot();self.spec=self.r.spec();self.cams=list(self.spec['cameras']);self.i=0
 def obs(self,tag,seconds=0):
  o=self.r.get_obs(cameras=self.cams,include_depth=True,seconds=seconds);o.save(str(RUN/tag));self.o=o;return o
 def joint(self,q,duration=2,opening=.04,tag='move'):
  q=np.asarray(q);a=np.r_[q,opening]
  o=self.r.submit('joint_position',a,dt=duration,cameras=self.cams,video='both',include_depth=True,video_fps=10,note=tag)
  o.save(str(RUN/(f'{self.i:02d}_'+tag)));self.i+=1;self.o=o
  print('MOVE',tag,'proprio',o.meta['proprio']['now'][:8],'left',o.meta['time_left_s'],flush=True);return o
 def cart(self,p,R,duration=2,opening=.04,tag='cart'):
  q=np.array(self.o.meta['proprio']['now'][:7]);target=ik(np.array(p),R,q);return self.joint(target,duration,opening,tag)

if __name__=='__main__':
 c=Controller();o=c.obs('perception');q=np.array(o.meta['proprio']['now'][:7]);T=fk(q)
 print('INITIAL FK',T,flush=True)
 estimate(o)
 for cam in c.cams:
  img=o.last[cam].copy();pix=project([T[:3,3],fk(q,site=0)[:3,3]],o.meta['cameras'][cam]);
  from PIL import ImageDraw
  im=Image.fromarray(img);dr=ImageDraw.Draw(im)
  for xy,color in zip(pix,['blue','red']):
   x,y=xy;dr.ellipse((x-3,y-3,x+3,y+3),fill=color)
  im.resize((960,720)).save(OUT/(cam+'_fk.png'))
