def estimate_pose(o,center0,R0,tag='pose'):
 pts=[]
 for cam,img in o.last.items():
  mask=binary_erosion(green(img)); pc=unproject(o.depth[cam],o.meta['cameras'][cam],mask)
  pc=pc[np.linalg.norm(pc-center0,axis=1)<.085];pts.extend(pc)
 pts=np.array(pts);np.save(OUT/(tag+'_points.npy'),pts)
 def residual(x):
  R=Rot.from_rotvec(x[3:]).as_matrix()@R0;local=(pts-x[:3])@R
  d=np.abs(local)-np.array([.02,.02,.03]);dist=np.linalg.norm(np.maximum(d,0),axis=1)+np.minimum(np.max(d,axis=1),0)
  return np.r_[dist,(x[:3]-center0)*.025,x[3:]*.0008]
 best=None
 for delta in [[0,0,0],[.004,0,0],[-.004,0,0]]:
  x0=np.r_[np.array(center0)+delta,0,0,0]
  sol=least_squares(residual,x0,bounds=(np.r_[np.array(center0)-.025,[-.35]*3],np.r_[np.array(center0)+.025,[.35]*3]),loss='soft_l1',f_scale=.001,max_nfev=300)
  cost=np.mean(residual(sol.x)**2)
  if best is None or cost<best[0]:best=(cost,sol.x)
 x=best[1];R=Rot.from_rotvec(x[3:]).as_matrix()@R0
 print('POSE',len(pts),'mse',best[0],'center',x[:3],'rot_change_deg',x[3:]*180/np.pi,flush=True)
 return x[:3],R

